-- Generated by execution/homework_sql.ts from docs/homework-2026-27/final/qaidah-hw3.json.
-- Loads homework 303 for 2026/27. Review, then apply with execution/apply_migration.ts.
-- Idempotent: re-running replaces the same papers again.

do $guard$ begin
  if exists (select 1 from submissions s join homeworks h on h.id = s.homework_id
             join auth.users u on u.id = s.student_id
             where h.number in (303) and coalesce(u.email, '') not like '%@bsms-demo.test') then
    raise exception 'a real student has work on a homework this load replaces; stop and ask';
  end if;
end $guard$;

-- Demo work on the replaced papers (answers, voice notes, attempts cascade).
delete from submissions where homework_id in (select id from homeworks where number in (303));
delete from questions where homework_id in (select id from homeworks where number in (303));

-- ── Homework 303: The Short Vowels and Tanwīn (10 marks, 8 questions)
insert into homeworks (number, title, series, total_marks, is_graded, week_id, due_at, course_id, ordinal)
select 303, $q$The Short Vowels and Tanwīn$q$, 'qaidah', 10, true, w.id, w.due_at, c.id, 3
  from weeks w, courses c where w.term_id = 1 and w.number = 3 and c.key = 'qaidah'
on conflict (number) do update set title = excluded.title, series = excluded.series, total_marks = excluded.total_marks,
  is_graded = true, course_id = excluded.course_id, ordinal = excluded.ordinal;
insert into questions (homework_id, position, qtype, scoring, prompt, points, is_bonus, is_task, options, rubric, needs_key)
select id, 1, 'text', 'exact', $q$What are the 3 short vowels?$q$, 3, false, false, null, $q$[{"id":"c1","desc":"Fatḥah (accept the Arabic name فتحة or the mark itself, ـَ)","marks":1},{"id":"c2","desc":"Kasrah (accept the Arabic name كسرة or the mark itself, ـِ)","marks":1},{"id":"c3","desc":"Ḍammah, also spelt Dhammah or Dhumma (accept the Arabic name ضمة or the mark itself, ـُ)","marks":1}]$q$::jsonb, false
  from homeworks where number = 303;
insert into questions (homework_id, position, qtype, scoring, prompt, points, is_bonus, is_task, options, rubric, needs_key)
select id, 2, 'text', 'exact', $q$What does tanwīn denote?$q$, 1, false, false, null, $q$[{"id":"c1","desc":"A double short vowel","marks":1}]$q$::jsonb, false
  from homeworks where number = 303;
insert into questions (homework_id, position, qtype, scoring, prompt, points, is_bonus, is_task, options, rubric, needs_key)
select id, 3, 'mcq', 'exact', $q$Which letter is said at the end of the word to pronounce tanwīn?$q$, 1, false, false, $q$[{"position":0,"label":"Option A","value":"ب","correct":false},{"position":1,"label":"Option B","value":"ن","correct":true},{"position":2,"label":"Option C","value":"ت","correct":false},{"position":3,"label":"Option D","value":"ء","correct":false},{"position":4,"label":"Option E","value":"ث","correct":false}]$q$::jsonb, null, false
  from homeworks where number = 303;
insert into questions (homework_id, position, qtype, scoring, prompt, points, is_bonus, is_task, options, rubric, needs_key)
select id, 4, 'text', 'exact', $q$Why is it important that we pronounce the ḥarakāt (short vowels) purely and correctly?$q$, 1, false, false, null, $q$[{"id":"c1","desc":"To make sure the meaning is preserved, as changing a ḥarakah can change the meaning","marks":1}]$q$::jsonb, false
  from homeworks where number = 303;
insert into questions (homework_id, position, qtype, scoring, prompt, points, is_bonus, is_task, options, rubric, needs_key)
select id, 5, 'text', 'manual', $q$Fatḥah. Read the following words and record yourself. Take your time and don't rush. Say each letter correctly, and give every letter the same length as the others.
The first picture shows each word as 3 separate letters in different colours. The second shows whole words. This builds your confidence to pick out each letter, then to say the word together.$q$, 1, false, true, null, null, false
  from homeworks where number = 303;
insert into questions (homework_id, position, qtype, scoring, prompt, points, is_bonus, is_task, options, rubric, needs_key)
select id, 6, 'text', 'manual', $q$Kasrah. Read the following words and record yourself. Take your time and don't rush. Say each letter correctly, and give every letter the same length as the others.$q$, 1, false, true, null, null, false
  from homeworks where number = 303;
insert into questions (homework_id, position, qtype, scoring, prompt, points, is_bonus, is_task, options, rubric, needs_key)
select id, 7, 'text', 'manual', $q$Ḍammah. Read the following words and record yourself. Take your time and don't rush. Say each letter correctly, and give every letter the same length as the others.$q$, 1, false, true, null, null, false
  from homeworks where number = 303;
insert into questions (homework_id, position, qtype, scoring, prompt, points, is_bonus, is_task, options, rubric, needs_key)
select id, 8, 'text', 'manual', $q$Read the following and record yourself. This checks everything you have covered so far.
Each colour is a different word. This builds the habit of seeing where a word begins and ends.$q$, 1, false, true, null, null, false
  from homeworks where number = 303;

-- Audio needs questions.media (migration 0048); skipped until it exists.
do $media$ begin
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'questions' and column_name = 'media') then
    update questions set media = $q${"images":[{"src":"/images/homework/qaidah/hw3-5-1.png","alt":"Qāʿidah exercise with fatḥah: each word as 3 separate letters","width":507,"height":291},{"src":"/images/homework/qaidah/hw3-5-2.png","alt":"Qāʿidah exercise with fatḥah: the whole words","width":515,"height":222}]}$q$::jsonb where position = 5 and homework_id = (select id from homeworks where number = 303);
    update questions set media = $q${"images":[{"src":"/images/homework/qaidah/hw3-6-1.png","alt":"Qāʿidah exercise with kasrah: each word as 3 separate letters","width":511,"height":295},{"src":"/images/homework/qaidah/hw3-6-2.png","alt":"Qāʿidah exercise with kasrah: the whole words","width":506,"height":145}]}$q$::jsonb where position = 6 and homework_id = (select id from homeworks where number = 303);
    update questions set media = $q${"images":[{"src":"/images/homework/qaidah/hw3-7-1.png","alt":"Qāʿidah exercise with ḍammah: each word as 3 separate letters","width":519,"height":224},{"src":"/images/homework/qaidah/hw3-7-2.png","alt":"Qāʿidah exercise with ḍammah: the whole words","width":513,"height":220}]}$q$::jsonb where position = 7 and homework_id = (select id from homeworks where number = 303);
    update questions set media = $q${"images":[{"src":"/images/homework/qaidah/hw3-8.png","alt":"Four short sentences, each word in its own colour","width":517,"height":139}]}$q$::jsonb where position = 8 and homework_id = (select id from homeworks where number = 303);
  end if;
end $media$;

select number, title, total_marks, (select count(*) from questions q where q.homework_id = h.id) as questions
  from homeworks h where number in (303) order by number;
